    @id = 0
    @events = []
    target = call('Target.createTarget', url: 'about:blank')['targetId']
    @session = call('Target.attachToTarget', targetId: target, flatten: true)['sessionId']
    call('Page.enable')
  end

  def close
    Process.kill('TERM', @pid)
    Process.wait(@pid)
  end

  def call(method, params = {})
    packet = { id: (@id += 1), method:, params: }
    packet[:sessionId] = @session if @session
    @send.write(JSON.generate(packet) + "\0")
    Timeout.timeout(10) do
      while r = @read.gets("\0")
        msg = JSON.parse(r.chop)
        if msg['id'] == @id
