    raise "Waiting for #{code} at #{js('location.pathname')}: #{js('document.body.innerText.slice(0,400)')}"
  end

  def dialog(accept)
    event = Timeout.timeout(10) do
      while !@events.any? { |m| m['method'] == 'Page.javascriptDialogOpening' }
        @events << JSON.parse(@read.gets("\0").chop)
